import type { PublicKeyCredentialDescriptorJSON } from '@simplewebauthn/browser'
import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import type { FieldName } from 'kea-forms'

import { getSocialLoginUrl } from 'lib/components/SocialLoginButton/socialLoginUrl'
import { BeginPasskeyLoginParams, passkeyLogic } from 'scenes/authentication/shared/passkeyLogic'
import { RecentLogin, forgetRecentLogin, readRecentLogins } from 'scenes/authentication/shared/recentLogins'

import { loginLogic } from './loginLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recentLoginsLogicValues {
    isPasswordLoginUnavailable: boolean // loginLogic
    hasRecentLogins: boolean
    isOtherLoginMethodsCollapsed: boolean
    otherLoginMethodsShown: boolean
    recentLogins: RecentLogin[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recentLoginsLogicActions {
    precheck: (args_0: { autoAttempt?: boolean; email: string }) => {
        autoAttempt?: boolean
        email: string
    } // loginLogic
    setLoginValue: (
        key: FieldName,
        value: any
    ) => {
        name: FieldName
        value: any
    } // loginLogic
    beginPasskeyLogin: (
        allowCredentials?: PublicKeyCredentialDescriptorJSON[] | undefined,
        params?: BeginPasskeyLoginParams | undefined
    ) => {
        allowCredentials: PublicKeyCredentialDescriptorJSON[] | undefined
        params: BeginPasskeyLoginParams | undefined
    } // passkeyLogic
    removeRecentLogin: (email: string) => {
        email: string
    }
    selectRecentLogin: (recentLogin: RecentLogin) => {
        recentLogin: RecentLogin
    }
    setRecentLogins: (recentLogins: RecentLogin[]) => {
        recentLogins: RecentLogin[]
    }
    showOtherLoginMethods: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recentLoginsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasRecentLogins: (recentLogins: RecentLogin[]) => boolean
        isOtherLoginMethodsCollapsed: (
            hasRecentLogins: any,
            otherLoginMethodsShown: boolean,
            isPasswordLoginUnavailable: boolean
        ) => boolean
    }
}

export type recentLoginsLogicType = MakeLogicType<
    recentLoginsLogicValues,
    recentLoginsLogicActions,
    Record<string, any>,
    recentLoginsLogicMeta
>

export const recentLoginsLogic = kea<recentLoginsLogicType>([
    path(['scenes', 'authentication', 'login', 'recentLoginsLogic']),
    connect(() => ({
        values: [loginLogic, ['isPasswordLoginUnavailable']],
        actions: [loginLogic, ['setLoginValue', 'precheck'], passkeyLogic, ['beginPasskeyLogin']],
    })),
    actions({
        setRecentLogins: (recentLogins: RecentLogin[]) => ({ recentLogins }),
        selectRecentLogin: (recentLogin: RecentLogin) => ({ recentLogin }),
        removeRecentLogin: (email: string) => ({ email }),
        showOtherLoginMethods: true,
    }),
    reducers({
        recentLogins: [
            [] as RecentLogin[],
            {
                setRecentLogins: (_, { recentLogins }) => recentLogins,
            },
        ],
        otherLoginMethodsShown: [
            false,
            {
                showOtherLoginMethods: () => true,
            },
        ],
    }),
    selectors({
        hasRecentLogins: [(s) => [s.recentLogins], (recentLogins: RecentLogin[]): boolean => recentLogins.length > 0],
        // The other methods are the only way in for an account without a password, so they never collapse
        isOtherLoginMethodsCollapsed: [
            (s) => [s.hasRecentLogins, s.otherLoginMethodsShown, s.isPasswordLoginUnavailable],
            (hasRecentLogins: boolean, otherLoginMethodsShown: boolean, isPasswordLoginUnavailable: boolean): boolean =>
                hasRecentLogins && !otherLoginMethodsShown && !isPasswordLoginUnavailable,
        ],
    }),
    listeners(({ actions }) => ({
        selectRecentLogin: ({ recentLogin: { email, method } }) => {
            if (method === 'passkey') {
                // No precheck here, because a precheck for an account with passkeys opens a second prompt
                actions.setLoginValue('email', email)
                actions.beginPasskeyLogin()
                return
            }
            if (method && method !== 'password') {
                window.location.assign(getSocialLoginUrl(method, { email }))
                return
            }
            // Without `autoAttempt`, so the click only fills the form and never leaves the page on its own
            actions.setLoginValue('email', email)
            actions.precheck({ email })
        },
        removeRecentLogin: ({ email }) => {
            actions.setRecentLogins(forgetRecentLogin(email))
        },
    })),
    afterMount(({ actions }) => {
        actions.setRecentLogins(readRecentLogins())
    }),
])
